/**
 * 千分位分组。
 *
 * **刻意不用 `toLocaleString()`**：它的输出由运行环境的 ICU 数据决定，
 * 服务端（Node）和浏览器可能给出不同的分组符（`1,234` / `1.234` / `1 234`）。
 * 同一份标记在两端渲染出两个字符串就是一次 hydration mismatch ——
 * 这是本项目反复踩到的同一类坑，数字格式化一律走这里。
 */
export function formatThousands(value: number): string {
  return String(value).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}
